def components(grid,bg):
 h,w=len(grid),len(grid[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   v=grid[r][c]
   if v==bg or (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c)); cells=[]
   while q:
    a,b=q.pop();cells.append((a,b))
    for x,y in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
     if 0<=x<h and 0<=y<w and (x,y) not in seen and grid[x][y]==v:
      seen.add((x,y));q.append((x,y))
   rs=[x for x,y in cells];cs=[y for x,y in cells]
   out.append((v,min(rs),min(cs),max(rs),max(cs),len(cells)))
 return out
